p=argparse.ArgumentParser();p.add_argument('evidence',type=pathlib.Path);p.add_argument('--out',required=True,type=pathlib.Path);a=p.parse_args();here=pathlib.Path(__file__).parent;f=here/'original-candidate-freeze.json';freeze=json.loads(f.read_text());x=json.loads((a.evidence/'original-post-b-hashes.json').read_text());b=json.loads((a.evidence/'b.json').read_text());assert x['status']=='pass' and not x['mismatches'] and x['read_only'] and x['no_workload_executed'];assert x['observed']=={v:freeze[v] for v in ['base','B']};assert x['expected_manifest_sha256']==hashlib.sha256(f.read_bytes()).hexdigest();assert b['finished_utc']<=x['started_utc']<=x['finished_utc'];a.out.write_text(json.dumps({'status':'pass','original_artifact_hashes':sum(len(v) for v in x['observed'].values()),'manifest_sha256':x['expected_manifest_sha256'],'original_timing_binaries_unchanged':True},indent=2)+'\n')
